mapper.select:
SELECT POS.ISSUE_PARTY_ID as issuePartyId, STR_TO_DATE(#{generateDate,jdbcType=VARCHAR},'%Y-%m-%d') as posDate, POS.PLAN_ASSET_ID as planAssetId, POS.ASSET_CODE as assetCode, POS.TOTAL_NUM as totalNum, POS.ISSUE_AMT as issueAmt, POS.UNINVEST_CASH as uninvestCash, POS.POS_NUM as posNum, POS.POS_AMT as posAmt, '01' status FROM CHB_BOT_AST_POS POS WHERE DATE_FORMAT(POS.POS_DATE,'%Y-%m-%d') = #{generateDate,jdbcType=VARCHAR}
and POS.ISCHL = '02'
and not exists (select 1 from CHB_BOT_AST_POS_SUB SUB where SUB.POS_DATE = POS.POS_DATE and SUB.PLAN_ASSET_ID = POS.PLAN_ASSET_ID and SUB.ASSET_CODE = POS.ASSET_CODE and SUB.SEND_STATUS in ('02','03'))

select f_guid() REGIST_SEQNO, POS.ISSUE_PARTY_ID as ISSUE_PARTY_ID, STR_TO_DATE(#{generateDate,jdbcType=VARCHAR},'%Y-%m-%d') as POS_DATE, ifnull(PLANASSET.ASSET_CODE_OLD,ifnull(PLANASSET.ASSET_CODE,pos.plan_asset_id)) as PLAN_ASSET_ID, ifnull(BOTASSET.ASSET_CODE_OLD,ifnull(BOTASSET.ASSET_CODE,pos.asset_code)) as ASSET_CODE, POS.TOTAL_NUM as TOTAL_NUM, POS.ISSUE_AMT as ISSUE_AMT, POS.UNINVEST_CASH as UNINVEST_CASH, POS.POS_NUM as POS_NUM, POS.POS_AMT as POS_AMT, '01' STATUS, '01' SEND_STATUS, #{chbSubmitDeadline,jdbcType=TIMESTAMP} CHB_SUBMIT_DEADLINE, #{submitDeadline,jdbcType=TIMESTAMP} SUBMIT_DEADLINE, POS.ORG_CODE ORG_CODE, POS.DEPT_CODE DEPT_CODE, 'system' CREATE_USER, now() CREATE_TIME, 'system' UPDATE_USER, now() UPDATE_TIME, #{statusDate,jdbcType=TIMESTAMP} STATUS_DATE FROM CHB_BOT_AST_POS POS LEFT JOIN CHB_ASSET_INFO PLANASSET ON PLANASSET.ASSET_CODE = POS.PLAN_ASSET_ID LEFT JOIN CHB_ASSET_INFO BOTASSET ON BOTASSET.ASSET_CODE = POS.ASSET_CODE
left join data_auth_notify_inst dis on (dis.business_id=POS.PLAN_ASSET_ID or dis.business_id='F28_'||POS.PLAN_ASSET_ID) and dis.model_type = '02' AND dis.DATA_TYPE in ('FINASSET12','PTL01')
WHERE DATE_FORMAT(POS.POS_DATE,'%Y-%m-%d') = #{generateDate,jdbcType=VARCHAR}
and POS.ISCHL = '02'
and dis.INSTITUTION_CODE =#{InstitutionCode,jdbcType=VARCHAR}
and not exists (select 1 from CHB_BOT_AST_POS_SUB SUB where SUB.POS_DATE = POS.POS_DATE and SUB.PLAN_ASSET_ID = ifnull(PLANASSET.ASSET_CODE_OLD,ifnull(PLANASSET.ASSET_CODE,pos.plan_asset_id)) and SUB.ASSET_CODE = ifnull(BOTASSET.ASSET_CODE_OLD,ifnull(BOTASSET.ASSET_CODE,pos.asset_code)) and SUB.SEND_STATUS in ('02','03') and SUB.STATUS != '03') and POS.STATUS != 'D' and POS.ASSET_CODE!='REMAININGCASH'

mapper.delete:
delete from CHB_BOT_AST_POS_SUB c


		DATE_FORMAT(c.POS_DATE,'%Y-%m-%d') = #{posDate,jdbcType=VARCHAR}


		and c.STATUS  = #{status,jdbcType=VARCHAR}


		and c.SEND_STATUS  = #{sendStatus,jdbcType=VARCHAR}



		and c.regist_seqno in (select  d.regist_seqno from CHB_BOT_AST_POS_SUB d
		left join data_auth_notify_inst dis
		on (dis.business_id=d.PLAN_ASSET_ID or dis.business_id='F28_'||d.PLAN_ASSET_ID)
		and dis.model_type = '02' AND dis.DATA_TYPE in ('FINASSET12','PTL01')
		where dis.INSTITUTION_CODE =#{InstitutionCode,jdbcType=VARCHAR}
		)
